css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 7px 12px; margin-bottom: 8px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 4px;}
.mz .ord-tabla{display: grid; grid-template-columns: repeat(5, 1fr); gap: 4px;}
.mz .ord-tabla .oc{border: 1.5px solid var(--bosque); border-radius: 6px; text-align: center; font-size: 13px; font-weight: 700; padding: 3px 2px;}
.mz .ord-tabla .oc b{display: block; font-size: 15px;}
.mz .ej-block:last-of-type{margin-bottom: 0;}
.mz .unir-grid{display: grid; grid-template-columns: 90px 1fr 150px; gap: 4px 0; align-items: center;}
.mz .unir-grid .u-cif{font-size: 19px; font-weight: 700; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 5px 0;}
.mz .unir-grid .u-pal{font-size: 15px; font-weight: 600; text-align: center; border: 1.5px solid var(--bosque); border-radius: 6px; padding: 6px 0;}
.mz .unir-grid .u-mid{height: 8px;}
.mz .esc-fila{display: flex; align-items: center; gap: 12px; font-size: 18px; font-weight: 700; margin-bottom: 7px;}
.mz .esc-fila .cif{min-width: 50px;}
.mz .esc-fila .linea-esc{flex: 1; border-bottom: 1.5px solid var(--bosque); height: 20px;}
.mz .cif-fila{display: flex; align-items: center; gap: 12px; font-size: 18px; font-weight: 700; margin-bottom: 6px;}
.mz .cif-fila .pal{min-width: 130px;}
.mz .cif-fila:last-child{margin-bottom: 0;}
.mz .cif-fila .caja-cif{width: 66px; height: 36px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .fila-pos{display: flex; gap: 6px; flex-wrap: wrap; margin-bottom: 6px;}
.mz .fila-pos .casilla{width: 42px; height: 42px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center; font-size: 17px; font-weight: 700;}
.mz .preg-pos{font-size: 15px; font-weight: 600; margin-top: 8px; line-height: 1.7;}
.mz .preg-pos .hueco{display: inline-block; width: 80px; border-bottom: 1.5px solid var(--bosque);}
